INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-bridal-lehengas', 'bridal-lehengas', 'Bridal Lehengas', 'Heavily embroidered lehengas crafted for the bride who wants every detail to be unforgettable.', 'https://images.pexels.com/photos/12411105/pexels-photo-12411105.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/12411105/pexels-photo-12411105.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 1, 'Bridal Lehengas Online | Offerlal Fashion', 'Shop hand-embroidered bridal lehengas in zardozi, zari and kundan work. Custom fitting available across India.', 'bridal lehenga,wedding lehenga,indian bridal wear');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-engagement-reception', 'engagement-reception-lehengas', 'Engagement & Reception Lehengas', 'Statement silhouettes in jewel tones and metallics for your engagement and reception look.', 'https://images.pexels.com/photos/30825616/pexels-photo-30825616.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/30825616/pexels-photo-30825616.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 2, 'Engagement & Reception Lehengas | Offerlal Fashion', 'Shop engagement and reception lehengas in sequin, thread and stone work for your second and third looks.', 'engagement lehenga,reception lehenga,reception gown');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-party-wear', 'party-wear-lehengas', 'Party Wear Lehengas', 'Lighter, easy-to-drape lehengas designed for sangeet nights and wedding season celebrations.', 'https://images.pexels.com/photos/13204680/pexels-photo-13204680.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/13204680/pexels-photo-13204680.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 3, 'Party Wear Lehengas Online | Offerlal Fashion', 'Shop party wear lehengas for sangeet, cocktail and festive occasions at accessible prices.', 'party wear lehenga,sangeet outfit,cocktail lehenga');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-sarees', 'sarees', 'Sarees', 'Banarasi, Kanjivaram and organza sarees for weddings, festivals and everyday elegance.', 'https://images.pexels.com/photos/20614154/pexels-photo-20614154.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/20614154/pexels-photo-20614154.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 4, 'Designer Sarees Online | Offerlal Fashion', 'Shop Banarasi silk, Kanjivaram and organza sarees with zari borders, curated for weddings and festive wear.', 'saree,banarasi saree,silk saree');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-anarkali-gowns', 'anarkali-gowns', 'Anarkali & Gowns', 'Flowing anarkali suits and fishtail gowns for receptions, cocktail parties and festive evenings.', 'https://images.pexels.com/photos/16612752/pexels-photo-16612752.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/16612752/pexels-photo-16612752.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 5, 'Anarkali Suits & Gowns | Offerlal Fashion', 'Shop designer anarkali suits and reception gowns in sequin, thread and stone embellishment.', 'anarkali suit,gown,reception gown');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-indo-western', 'indo-western-fusion', 'Indo-Western Fusion', 'Contemporary silhouettes that blend Indian craft with western drapes, for the modern occasion dresser.', 'https://images.pexels.com/photos/19248233/pexels-photo-19248233.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/19248233/pexels-photo-19248233.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 6, 'Indo-Western Fusion Wear | Offerlal Fashion', 'Shop indo-western fusion dresses and pre-draped gowns blending Indian embroidery with contemporary cuts.', 'indo western dress,fusion wear,pre-draped gown');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-sharara-gharara', 'sharara-gharara-sets', 'Sharara & Gharara Sets', 'Flared sharara and gharara sets for mehendi, haldi and sangeet festivities.', 'https://images.pexels.com/photos/15751055/pexels-photo-15751055.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/15751055/pexels-photo-15751055.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 7, 'Sharara & Gharara Sets | Offerlal Fashion', 'Shop sharara and gharara sets in cotton, silk and georgette for mehendi and haldi celebrations.', 'sharara set,gharara set,mehendi outfit');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-kids-ethnic', 'kids-ethnic-wear', 'Kids Ethnic Wear', 'Miniature lehengas, sherwanis and festive sets so the little ones match the celebration.', 'https://images.pexels.com/photos/30723693/pexels-photo-30723693.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/30723693/pexels-photo-30723693.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 8, 'Kids Ethnic Wear | Offerlal Fashion', 'Shop festive ethnic wear for kids — lehengas, sherwanis and co-ord sets for weddings and celebrations.', 'kids ethnic wear,kids lehenga,kids sherwani');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-bridal-jewellery', 'bridal-jewellery', 'Bridal Jewellery', 'Kundan, polki and temple jewellery sets to complete the bridal look, sold individually or as sets.', 'https://images.pexels.com/photos/35586107/pexels-photo-35586107.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/35586107/pexels-photo-35586107.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 9, 'Bridal Jewellery Sets | Offerlal Fashion', 'Shop kundan, polki and temple jewellery sets — necklaces, maang tikka, earrings and bangles for the bride.', 'bridal jewellery,kundan set,polki jewellery');
INSERT INTO dbo.Categories (Id, Slug, Name, Description, HeroImageUrl, ThumbnailUrl, ParentId, DisplayOrder, SeoTitle, SeoDescription, SeoKeywords) VALUES ('cat-accessories', 'dupattas-clutches-footwear', 'Dupattas, Clutches & Footwear', 'The finishing pieces — net and organza dupattas, potli bags and embellished juttis.', 'https://images.pexels.com/photos/1444441/pexels-photo-1444441.jpeg?auto=compress&cs=tinysrgb&w=1600', 'https://images.pexels.com/photos/1444441/pexels-photo-1444441.jpeg?auto=compress&cs=tinysrgb&w=600', NULL, 10, 'Dupattas, Clutches & Footwear | Offerlal Fashion', 'Shop dupattas, potli bags and embellished juttis to complete your festive and bridal look.', 'dupatta,potli bag,jutti');
