INSERT INTO dbo.Products (Id, Slug, Name, Sku, CategoryId, SubCategory, Description, ShortDescription, Fabric, WorkDetails, BlouseDetails, DupattaDetails, AvailableSizes, Price, CompareAtPrice, Currency, Rating, ReviewCount, StockStatus, IsBestseller, IsNewArrival, IsFeatured, IsBridal, CareInstructions, DeliveryStandardDays, DeliveryExpressDays, WeightGrams, Tags, SeoTitle, SeoDescription, SeoKeywords, CreatedAt, UpdatedAt) VALUES ('prod-001', 'maroon-zari-embroidered-bridal-lehenga', 'Maroon Zari Embroidered Bridal Lehenga Set', 'OF-BR-1001', 'cat-bridal-lehengas', 'Heavy Bridal', 'A regal maroon bridal lehenga hand-embroidered with intricate zari, zardozi and dabka work across the skirt and blouse, paired with a net dupatta finished in scalloped gota lace. Crafted on a raw silk base for structure and drape.', 'Hand-embroidered zari bridal lehenga in deep maroon raw silk.', 'Raw Silk with Net Dupatta', 'Hand Zardozi, Zari and Dabka embroidery with stone work', 'Sweetheart neck blouse with zardozi sleeves, fully lined', 'Net dupatta with scalloped gota lace border', '["S","M","L","XL","Custom"]', 68500, 82000, 'INR', 4.7, 34, 'made-to-order', 1, 0, 1, 1, '["Dry clean only","Store folded in muslin cloth","Avoid direct sunlight and perfume contact"]', 12, 7, NULL, '["maroon","zari","bridal","raw-silk","heavy-work"]', 'Maroon Zari Embroidered Bridal Lehenga Set | Offerlal Fashion', 'Shop the Maroon Zari Embroidered Bridal Lehenga Set - hand zardozi work on raw silk, custom blouse stitching available.', 'maroon,zari,bridal,raw-silk,heavy-work', '2026-01-14T10:00:00.000Z', '2026-01-14T10:00:00.000Z');
INSERT INTO dbo.Products (Id, Slug, Name, Sku, CategoryId, SubCategory, Description, ShortDescription, Fabric, WorkDetails, BlouseDetails, DupattaDetails, AvailableSizes, Price, CompareAtPrice, Currency, Rating, ReviewCount, StockStatus, IsBestseller, IsNewArrival, IsFeatured, IsBridal, CareInstructions, DeliveryStandardDays, DeliveryExpressDays, WeightGrams, Tags, SeoTitle, SeoDescription, SeoKeywords, CreatedAt, UpdatedAt) VALUES ('prod-002', 'red-zardozi-bridal-lehenga', 'Red Zardozi Bridal Lehenga Set', 'OF-BR-1002', 'cat-bridal-lehengas', 'Heavy Bridal', 'A classic red bridal lehenga with dense zardozi embroidery and mirror accents, designed for brides who want traditional grandeur. The flared silhouette is built on a structured net-over-silk base for a full, statement look.', 'Dense zardozi bridal lehenga in classic red with mirror accents.', 'Net over Silk', 'Zardozi and mirror work with gota border', 'Full-sleeve zardozi blouse with sweetheart neckline', 'Net dupatta with heavy zardozi border', '["S","M","L","XL","Custom"]', 92000, 110000, 'INR', 4.8, 41, 'made-to-order', 1, 0, 0, 1, '["Dry clean only","Store folded in muslin cloth","Avoid direct sunlight and perfume contact"]', 12, 7, NULL, '["red","zardozi","bridal","mirror-work"]', 'Red Zardozi Bridal Lehenga Set | Offerlal Fashion', 'Shop the Red Zardozi Bridal Lehenga Set - traditional grandeur with dense zardozi and mirror work.', 'red,zardozi,bridal,mirror-work', '2026-01-20T10:00:00.000Z', '2026-01-20T10:00:00.000Z');
INSERT INTO dbo.Products (Id, Slug, Name, Sku, CategoryId, SubCategory, Description, ShortDescription, Fabric, WorkDetails, BlouseDetails, DupattaDetails, AvailableSizes, Price, CompareAtPrice, Currency, Rating, ReviewCount, StockStatus, IsBestseller, IsNewArrival, IsFeatured, IsBridal, CareInstructions, DeliveryStandardDays, DeliveryExpressDays, WeightGrams, Tags, SeoTitle, SeoDescription, SeoKeywords, CreatedAt, UpdatedAt) VALUES ('prod-003', 'wine-velvet-bridal-lehenga', 'Wine Velvet Bridal Lehenga Set', 'OF-BR-1003', 'cat-bridal-lehengas', 'Heavy Bridal', 'A winter-bridal favourite - plush wine velvet embroidered with kundan and dabka work, offering rich texture and weight for a dramatic silhouette. Comes with a matching velvet potli and dupatta.', 'Plush wine velvet bridal lehenga with kundan and dabka work.', 'Velvet', 'Kundan and dabka embroidery with pearl detailing', 'Deep V-neck velvet blouse with kundan work', 'Velvet dupatta with kundan border', '["S","M","L","XL","Custom"]', 78500, 95000, 'INR', 4.6, 22, 'made-to-order', 0, 0, 0, 1, '["Dry clean only","Store folded in muslin cloth","Avoid direct sunlight and perfume contact"]', 12, 7, NULL, '["wine","velvet","bridal","kundan"]', 'Wine Velvet Bridal Lehenga Set | Offerlal Fashion', 'Shop the Wine Velvet Bridal Lehenga Set - plush velvet with kundan and dabka embroidery.', 'wine,velvet,bridal,kundan', '2026-02-02T10:00:00.000Z', '2026-02-02T10:00:00.000Z');
