INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-01', 'prod-001', 'cust-001', 'Ananya Sharma', 'Delhi', 5, 'Exceeded expectations', 'Absolutely loved my bridal lehenga. The zari detailing was even more beautiful in person, and the custom blouse fit perfectly on the first try.', 1, '2026-03-02T09:00:00.000Z', 24);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-02', 'prod-001', 'cust-010', 'Pooja Rathore', 'Udaipur', 5, 'Worth every rupee', 'The raw silk quality is genuinely premium, not what I expected at this price point. Delivered a day ahead of the promised date too.', 1, '2026-03-10T09:00:00.000Z', 15);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-03', 'prod-002', 'cust-002', 'Priya Reddy', 'Hyderabad', 5, 'Stunning zardozi work', 'Wore this for my wedding reception and got compliments all night. The mirror work catches light beautifully in photos.', 1, '2026-02-18T09:00:00.000Z', 31);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-04', 'prod-004', 'cust-012', 'Sanya Kapoor', 'Mumbai', 4, 'Beautiful but arrived tight', 'The pearl embroidery is gorgeous and exactly as pictured, but I had to get the waist let out slightly despite sending my measurements. Support team sorted it quickly.', 1, '2026-03-01T09:00:00.000Z', 9);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-05', 'prod-005', 'cust-016', 'Rhea Desai', 'Ahmedabad', 5, 'Show-stopping gold lehenga', 'This lehenga photographed even better than the website images. The kundan work is heavier than I expected in the best way.', 1, '2026-04-05T09:00:00.000Z', 18);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-06', 'prod-008', 'cust-002', 'Priya Reddy', 'Hyderabad', 5, 'A true heirloom piece', 'You can feel the difference in the hand embroidery quality compared to machine work. This will genuinely be passed down in our family.', 1, '2026-04-20T09:00:00.000Z', 12);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-07', 'prod-009', 'cust-003', 'Kavya Iyer', 'Chennai', 4, 'Great for the reception', 'The sequin work really shines under event lighting. Sizing ran slightly large so consider going one size down.', 1, '2026-04-15T09:00:00.000Z', 7);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-08', 'prod-015', 'cust-006', 'Riya Bansal', 'Jaipur', 5, 'Perfect for sangeet night', 'Danced all night in this and it held up beautifully — light, comfortable, and the mirror work never felt scratchy.', 1, '2026-05-20T09:00:00.000Z', 20);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-09', 'prod-017', 'cust-007', 'Anjali Gupta', 'Lucknow', 5, 'Loved the mustard shade', 'Wore this for haldi and the colour was even richer in person. Got so many requests for the brand name.', 1, '2026-05-25T09:00:00.000Z', 16);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-10', 'prod-023', 'cust-014', 'Tanya Chopra', 'Delhi', 5, 'Beautiful Banarasi weave', 'The zari border is dense and well-finished, not the thin machine-woven kind you sometimes get online. Draped beautifully.', 1, '2026-03-05T09:00:00.000Z', 22);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-11', 'prod-024', 'cust-018', 'Vidya Pillai', 'Trivandrum', 5, 'A proper Kanjivaram', 'As someone from Kerala who has bought many Kanjivarams, I can vouch this is genuine quality silk with a good weight to the drape.', 1, '2026-03-15T09:00:00.000Z', 14);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-12', 'prod-031', 'cust-012', 'Sanya Kapoor', 'Mumbai', 3, 'Nice gown, slow delivery', 'The gown itself is lovely and fits true to size, but it arrived four days later than the estimate, which was stressful before the event.', 1, '2026-05-10T09:00:00.000Z', 6);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-13', 'prod-039', 'cust-011', 'Ishita Malhotra', 'Chandigarh', 4, 'Comfortable for a long day', 'Wore this through a full day of mehendi functions and it stayed comfortable. The gota work is neat and evenly finished.', 1, '2026-04-22T09:00:00.000Z', 10);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-14', 'prod-040', 'cust-015', 'Kritika Joshi', 'Pune', 5, 'Bright and festive', 'This yellow gharara made all our haldi photos pop. Fabric is breathable even for an outdoor function in April.', 1, '2026-04-28T09:00:00.000Z', 13);
INSERT INTO dbo.Reviews (Id, ProductId, CustomerId, CustomerName, CustomerCity, Rating, Title, Comment, VerifiedPurchase, CreatedAt, HelpfulCount) VALUES ('rev-15', 'prod-049', 'cust-010', 'Pooja Rathore', 'Udaipur', 5, 'Elevated my whole look', 'The kundan choker set paired perfectly with my lehenga and the maang tikka adjusts easily to fit any hair parting.', 1, '2026-04-02T09:00:00.000Z', 19);
